// Flow: how a dictation is put on the clipboard.
//
// Clipboard managers (Maccy, Paste and similar) record everything that is copied. A dictation is
// a paste, not something Jordan copied on purpose, so it carries the community markers
// (nspasteboard.org): transient, auto-generated and concealed. Managers that honour them skip it.
// Paste targets still receive the text as normal.

import AppKit

enum DictationPasteboard {
    static let transient = NSPasteboard.PasteboardType("org.nspasteboard.TransientType")
    static let autoGenerated = NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType")
    static let concealed = NSPasteboard.PasteboardType("org.nspasteboard.ConcealedType")

    /// Replaces the clipboard with `text` plus the markers. Returns false if the text could not be written.
    @discardableResult
    static func write(_ text: String, to pasteboard: NSPasteboard = .general) -> Bool {
        pasteboard.clearContents()
        pasteboard.declareTypes([.string, transient, autoGenerated, concealed], owner: nil)
        let wrote = pasteboard.setString(text, forType: .string)
        pasteboard.setData(Data(), forType: transient)
        pasteboard.setData(Data(), forType: autoGenerated)
        pasteboard.setData(Data(), forType: concealed)
        return wrote
    }
}
